INSERT INTO product (product_key, name, frame, mass_limit_kg) VALUES
    ('aerial-screw', 'Aerial screw working replica (Paris Manuscript B, f. 83v)', 'z up on the mast axis with z = 0 on the floor, x towards the hydraulic skid, y to its left; mm, the frame of modules/cad/aerial_screw.py. Sail diameter 4669 (a 1:2 replica of the folio''s 8 braccia radius), deck top at z 600, mast top at 3532; the sail is one left-handed turn from z 2182 to 2934.', NULL),
    ('antikythera', 'Antikythera mechanism, simplified interpretation', 'x to the right seen from the front dial, y towards the back of the case, z up; x = z = 0 on the main drive axis b, y = 0 on the front face of the bronze front plate; mm, the frame of modules/cad/antikythera.py. Case 180 x 96 x 340: front door at y -16, back door to y 80, plates at y 0 to 3 and 62 to 65; gears are plain discs at pitch diameter (module 0.55) in layers between y 6 and 58.5.', NULL),
    ('cart', 'Self-propelled cart (Codex Atlanticus, f. 812r)', 'x forward in the direction of travel, y to the left, z up with z = 0 on the ground under the drive axle centre; mm, the frame of modules/cad/cart.py. Length 1700 (drive wheel front at x 500, steering wheel rear at x -1200), width 1420 over the drive wheels (centre planes at y +/-680), drive wheel diameter 1000 with the axle at z 500, spring shaft heads at z 740.', NULL),
    ('cubesat', '1U CubeSat, authored demonstrator', 'z along the rails with z = 0 on the outer face of the -Z end plate (the face inserted first into the dispenser), x and y from the axis of the rail square; mm, the frame of modules/cad/cubesat.py. Body 100 x 100 x 100 with |x|, |y| <= 50, rails 8.5 mm square at the corners from z -6.75 to 106.75 (113.5 overall), board stack at z 32, 47.24 and 62.48, solar panel boards 1.6 mm outside the +X, +Y and +Z faces, antenna module 4 mm outside the -X face.', 2.000),
    ('difference-engine', 'Difference engine No. 2 design, authored reconstruction', 'x along the row of columns from the output end, y towards the output apparatus, z up with z = 0 on the floor; mm. Result column at x 450, pitch 270, camshaft at x 2730, crank grip to x 3340, top rail at z 2090; the frame of modules/cad/difference_engine.py. Eight columns of 31 figure wheels at pitch 50 from z 420, camshaft with 14 cams at x 2730, driving train x 2880 to 3340, output apparatus x -160 to 680 in front (y 300 to 950); overall x -160 to 3340, y -410 to 950, z 0 to 2090.', NULL),
    ('glider', 'Lilienthal Normalsegelapparat (1894), authored reconstruction', 'x aft from the nose of the frame (the front of the bumper bow) at the centreline, y to the pilot''s right, z up with z = 0 on the top face of the rib hub fittings; mm, the frame of modules/cad/glider.py. Span 6.7 m (front rib tips at y +/-3349), hubs of the eight radial ribs per wing at (400, +/-400), cross rod axis at z -28, hoop of 760 mm centred at x 700, kingpost head at z 1050, lower post foot at z -720, tail boom to x 4850, tail plane hinge at x 3910, fin post at x 4000.', NULL),
    ('ornithopter', 'Ornithopter ground demonstrator (Paris Manuscript B, f. 74v)', 'x aft from the frame nose, y to the pilot''s right, z up with z = 0 on the keel beam axis; mm, the frame of modules/cad/ornithopter.py. Span 11.0 m (wing tips at y +/-5500), frame x 0 to 3600 with the tail plane to 4900, skid underside at z -580, control post top at 1090.', 260.500),
    ('rover', 'Six-wheel rocker-bogie rover, authored', 'x forward in the direction of travel, y to the left, z up with z = 0 on the ground under the wheel contact points; mm, the frame of modules/cad/rover.py. Wheel stations at x 330 (front, steered), -30 (middle) and -330 (rear, steered), wheel centre planes at y +/-340, axles at z 100, wheel diameter 200; suspension tubes in the planes y +/-240 with the rocker pivots at (0, +/-240, 320) and the bogie pivots at (-180, +/-240, 230); body 560 x 400 from z 220 to 380, lid to 383, differential bar at z 420, camera housing top at z 660.', NULL),
    ('steam-engine', 'Watt rotative beam engine, simplified (1788 type)', 'x from the boiler towards the flywheel, y across the engine with the flywheel on the negative side, z up with z = 0 on the floor; mm, the frame of modules/cad/steam_engine.py. Bed frame top at z 300, cylinder axis at x 600, beam pivot at x 3100, z 4000, crankshaft at x 5600, z 2100, flywheel diameter 3500 centred at y -900, boiler from x -3000 to -1200; overall x -3000 to 7350, beam top at z 4250.', NULL),
    ('wind-turbine', '5 MW reference-class wind turbine, authored', 'z up with z = 0 at the tower base flange, x downwind along the nacelle axis, y to the left seen from upwind; mm, the frame of modules/cad/wind_turbine.py. Hub centre at (-5000, 0, 90000), main shaft axis horizontal at z 90000, blade 1 up with its tip at z 153000, tower sections from z 200 to 87400 with joint flanges at 21900, 43800 and 65700, yaw bearing 87600 to 87900, nacelle cover x -3200 to 9800, y +/-3000, z 87800 to 93000, nose cone to x -9200; onshore anchor cage at z -2200, offshore transition piece and monopile from z -200 down to -56000.', NULL);
